# break and continue in an except* block are refused wherever they stand, code that cannot be reached included.
try: DEAD = ['return\n{s}', 'raise E\n{s}', 'if 0:\n    {s}', 'while False:\n    {s}', 'if not 1:\n    {s}', 'while 1:\n    pass\nelse:\n    {s}', 'if 1:\n    pass\nelse:\n    {s}', '{s}']
except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + "> in: DEAD = ['return\\n{s}', 'raise E\\n{s}', 'if 0:\\n {s}', 'while False:\\n...")
try:
    def indent(text, by):
        return '\n'.join(' ' * by + line for line in text.split('\n'))
except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + '> in: def indent(text, by):')
try:
    for statement in ('break', 'continue', 'return', 'pass'):
        for dead in DEAD:
            if 'while' in dead and statement in ('break', 'continue') and 'else' not in dead:
                continue
            try: source = 'def f():\n    for i in x:\n        try:\n            pass\n        except* E:\n' + indent(dead.format(s=statement), 12) + '\n'
            except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + "> in: source = 'def f():\\n for i in x:\\n try:\\n pass\\n except* E:\\n' + inde...")
            try:
                compile(source, '<s>', 'exec')
                print('statement [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', statement)
                print('repr(dead) [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', repr(dead))
                print('compiles')
            except SyntaxError as e:
                print('statement [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', statement)
                print('repr(dead) [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', repr(dead))
                print('e.msg [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', e.msg)
                print('e.lineno [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', e.lineno)
                print('e.offset [' + 'statement=' + (repr(statement) if type(statement) in (str, int, float, bytes, bool, type(None)) or (type(statement) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in statement)) else statement.__name__ if type(statement) is type else type(statement).__name__) + ", " + 'dead=' + (repr(dead) if type(dead) in (str, int, float, bytes, bool, type(None)) or (type(dead) is tuple and all(type(_i) in (str, int, float, bytes, bool, type(None)) for _i in dead)) else dead.__name__ if type(dead) is type else type(dead).__name__) + '] =>', e.offset)
except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + "> in: for statement in ('break', 'continue', 'return', 'pass'):")
